CREATE TABLE roles (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, name VARCHAR(50) NOT NULL UNIQUE, description VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE admin_users (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, username VARCHAR(80) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(160) NOT NULL, role_id BIGINT UNSIGNED NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_login DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (role_id) REFERENCES roles(id));
CREATE TABLE courses (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, code VARCHAR(30) NOT NULL UNIQUE, name VARCHAR(160) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE academic_periods (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, school_year VARCHAR(20) NOT NULL, semester VARCHAR(30) NOT NULL, is_current BOOLEAN NOT NULL DEFAULT FALSE, is_active BOOLEAN NOT NULL DEFAULT TRUE, UNIQUE KEY academic_period (school_year, semester));
CREATE TABLE students (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id VARCHAR(40) NOT NULL UNIQUE, kumosoft_id VARCHAR(40) NULL UNIQUE, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100), last_name VARCHAR(100) NOT NULL, birth_date DATE NOT NULL, course_id BIGINT UNSIGNED NOT NULL, voucher_id BIGINT UNSIGNED NULL UNIQUE, year_level TINYINT UNSIGNED, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (course_id) REFERENCES courses(id), INDEX verify_lookup (student_id, last_name, birth_date, course_id, is_active));
CREATE TABLE satp_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_satp_account (student_id));
CREATE TABLE schoology_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_schoology_account (student_id));
CREATE TABLE kumosoft_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, username VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_kumosoft_account (student_id));
CREATE TABLE institutional_email_accounts (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, email_address VARCHAR(255) NOT NULL, encrypted_password TEXT NOT NULL, password_iv VARCHAR(50) NOT NULL, password_auth_tag VARCHAR(50) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), UNIQUE KEY one_institutional_email (student_id), UNIQUE KEY unique_email_address (email_address));
CREATE TABLE wifi_vouchers (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, voucher_code VARCHAR(255) NOT NULL UNIQUE, is_active BOOLEAN NOT NULL DEFAULT TRUE, is_assigned BOOLEAN NOT NULL DEFAULT FALSE, is_released BOOLEAN NOT NULL DEFAULT FALSE, assigned_at DATETIME NULL, released_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, INDEX available_voucher (is_active, is_assigned));
ALTER TABLE students ADD CONSTRAINT fk_students_voucher FOREIGN KEY (voucher_id) REFERENCES wifi_vouchers(id);
CREATE TABLE kiosks (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, kiosk_code VARCHAR(80) NOT NULL UNIQUE, kiosk_name VARCHAR(120) NOT NULL, location VARCHAR(160), secret_hash VARCHAR(255) NOT NULL, is_active BOOLEAN NOT NULL DEFAULT TRUE, last_seen DATETIME NULL, ip_address VARCHAR(64) NULL, hostname VARCHAR(255) NULL, uptime_seconds BIGINT UNSIGNED NULL, browser_status VARCHAR(40) NULL, current_page VARCHAR(500) NULL, mac_address VARCHAR(32) NULL, operating_system VARCHAR(160) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
CREATE TABLE kiosk_commands (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, kiosk_id BIGINT UNSIGNED NOT NULL, command VARCHAR(40) NOT NULL, channel ENUM('BROWSER', 'AGENT') NOT NULL DEFAULT 'BROWSER', status ENUM('QUEUED', 'DISPATCHED', 'COMPLETED', 'FAILED', 'UNSUPPORTED') NOT NULL DEFAULT 'QUEUED', result_text VARCHAR(1000) NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, dispatched_at DATETIME NULL, completed_at DATETIME NULL, INDEX kiosk_command_poll (kiosk_id, channel, status, id), FOREIGN KEY (kiosk_id) REFERENCES kiosks(id) ON DELETE CASCADE);
CREATE TABLE credential_transactions (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NULL, kiosk_code VARCHAR(80) NULL, transaction_type ENUM('VERIFY','VIEW_CREDENTIALS','RELEASE_VOUCHER','ASSIGN_VOUCHER') NOT NULL, success BOOLEAN NOT NULL, ip_address VARCHAR(64), user_agent VARCHAR(255), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (student_id) REFERENCES students(id), INDEX recent_transactions (created_at));
CREATE TABLE audit_logs (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, admin_user_id BIGINT UNSIGNED NULL, action VARCHAR(100) NOT NULL, module VARCHAR(80) NOT NULL, record_id VARCHAR(80), description TEXT, ip_address VARCHAR(64), created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY (admin_user_id) REFERENCES admin_users(id));
CREATE TABLE password_reset_requests (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, student_id BIGINT UNSIGNED NOT NULL, credential_type ENUM('SATP', 'SCHOOLOGY', 'KUMOSOFT', 'EMAIL', 'VOUCHER') NOT NULL, request_kind ENUM('PASSWORD_RESET', 'ACCOUNT_CREATION', 'VOUCHER_REQUEST') NOT NULL DEFAULT 'PASSWORD_RESET', request_reason VARCHAR(500) NULL, status ENUM('PENDING', 'COMPLETED', 'REJECTED') NOT NULL DEFAULT 'PENDING', kiosk_code VARCHAR(80) NULL, requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, resolved_at DATETIME NULL, resolved_by BIGINT UNSIGNED NULL, pending_key VARCHAR(120) GENERATED ALWAYS AS (IF(status='PENDING', CONCAT(student_id, '-', credential_type, '-', request_kind), NULL)) STORED, FOREIGN KEY (student_id) REFERENCES students(id), FOREIGN KEY (resolved_by) REFERENCES admin_users(id), INDEX reset_request_queue (status, requested_at), INDEX student_reset_requests (student_id, credential_type, status), UNIQUE KEY one_pending_credential_request (pending_key));
CREATE TABLE kiosk_reminders (id BIGINT UNSIGNED PRIMARY KEY AUTO_INCREMENT, placement ENUM('BANNER', 'GUIDELINE', 'TIP') NOT NULL DEFAULT 'GUIDELINE', title VARCHAR(160) NOT NULL, message VARCHAR(500) NULL, sort_order INT NOT NULL DEFAULT 0, is_active BOOLEAN NOT NULL DEFAULT TRUE, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX active_reminders (is_active, placement, sort_order));
INSERT INTO kiosk_reminders (placement, title, message, sort_order) VALUES ('BANNER', 'Use your correct Course, Last Name, and Birthday.', 'Your information must match the records.', 10), ('GUIDELINE', 'For enrolled NDMU students only.', 'Credential and voucher access is exclusive to enrolled students.', 20), ('GUIDELINE', 'One voucher per student.', 'Please use your assigned voucher responsibly.', 30), ('GUIDELINE', 'Keep your credentials private.', 'Do not share passwords or voucher codes with anyone.', 40), ('GUIDELINE', 'Need help?', 'Submit a password reset request or proceed to the ICT/MIS Office.', 50), ('TIP', 'Double-check your information.', 'Confirm your course, last name, and birthday before submitting.', 60);
CREATE TABLE credential_module_controls (module_key ENUM('VOUCHER', 'SATP', 'SCHOOLOGY', 'KUMOSOFT', 'EMAIL', 'KIOSK') PRIMARY KEY, is_visible BOOLEAN NOT NULL DEFAULT TRUE, is_maintenance BOOLEAN NOT NULL DEFAULT FALSE, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP);
INSERT INTO credential_module_controls (module_key) VALUES ('VOUCHER'), ('SATP'), ('SCHOOLOGY'), ('KUMOSOFT'), ('EMAIL'), ('KIOSK');
